// AES-128, the FIPS-197 block cipher itself — every encrypt/decrypt box in
// the diagram calls encryptBlock/decryptBlock on one 16-byte block.
const SBOX = new Uint8Array(256);
const INV = new Uint8Array(256);
{
  let p = 1;
  let q = 1;
  do {
    p ^= ((p << 1) ^ (p & 0x80 ? 0x1b : 0)) & 255;
    q = (q ^ (q << 1)) & 255;
    q = (q ^ (q << 2)) & 255;
    q = (q ^ (q << 4)) & 255;
    if (q & 0x80) q ^= 0x09;
    const rot = (x, s) => ((x << s) | (x >> (8 - s))) & 255;
    SBOX[p] = q ^ rot(q, 1) ^ rot(q, 2) ^ rot(q, 3) ^ rot(q, 4) ^ 0x63;
  } while (p !== 1);
  SBOX[0] = 0x63;
  for (let i = 0; i < 256; i++) INV[SBOX[i]] = i;
}

const xtime = (x) => ((x << 1) ^ (x & 0x80 ? 0x1b : 0)) & 255;
const mul = (x, y) => {
  let r = 0;
  for (; y; y >>= 1) {
    if (y & 1) r ^= x;
    x = xtime(x);
  }
  return r;
};

const expandKey = (key) => {
  const w = new Uint8Array(176);
  w.set(key);
  let rcon = 1;
  for (let i = 16; i < 176; i += 4) {
    let t = [w[i - 4], w[i - 3], w[i - 2], w[i - 1]];
    if (i % 16 === 0) {
      t = [SBOX[t[1]] ^ rcon, SBOX[t[2]], SBOX[t[3]], SBOX[t[0]]];
      rcon = xtime(rcon);
    }
    for (let j = 0; j < 4; j++) w[i + j] = w[i - 16 + j] ^ t[j];
  }
  return w;
};

const addKey = (s, w, r) => {
  for (let i = 0; i < 16; i++) s[i] ^= w[r * 16 + i];
};
// state is column-major: flat index 4*col + row; dir 1 = ShiftRows, -1 = inverse
const shift = (s, dir) => {
  const t = s.slice();
  for (let c = 0; c < 4; c++)
    for (let r = 0; r < 4; r++) s[4 * c + r] = t[4 * ((c + dir * r + 4) & 3) + r];
};
const mix = (s, m) => {
  for (let c = 0; c < 4; c++) {
    const a = s.slice(4 * c, 4 * c + 4);
    for (let r = 0; r < 4; r++)
      s[4 * c + r] =
        mul(a[r], m[0]) ^
        mul(a[(r + 1) & 3], m[1]) ^
        mul(a[(r + 2) & 3], m[2]) ^
        mul(a[(r + 3) & 3], m[3]);
  }
};

const encryptBlock = (w, block) => {
  const s = Uint8Array.from(block);
  addKey(s, w, 0);
  for (let r = 1; r <= 10; r++) {
    for (let i = 0; i < 16; i++) s[i] = SBOX[s[i]];
    shift(s, 1);
    if (r < 10) mix(s, [2, 3, 1, 1]);
    addKey(s, w, r);
  }
  return s;
};
const decryptBlock = (w, block) => {
  const s = Uint8Array.from(block);
  addKey(s, w, 10);
  for (let r = 9; r >= 0; r--) {
    shift(s, -1);
    for (let i = 0; i < 16; i++) s[i] = INV[s[i]];
    addKey(s, w, r);
    if (r > 0) mix(s, [14, 11, 13, 9]);
  }
  return s;
};

({ expandKey, encryptBlock, decryptBlock });

